@Singleton
@Plugin(id = ARTIFACT_ID, name = PomData.NAME, version = PomData.VERSION,
        url = PomData.URL, description = PomData.DESCRIPTION)
public class ChangeSkinSponge implements PlatformPlugin<CommandSource> {

    private final Path dataFolder;
    private final Logger logger;
    private final Injector injector;

    private final ChangeSkinCore core = new ChangeSkinCore(this);
    private final SpongeSkinAPI api = new SpongeSkinAPI(this);

    private boolean initialized;

    //We will place more than one config there (i.e. H2/SQLite database) -> sharedRoot = false
    @Inject
    ChangeSkinSponge(Logger logger, @ConfigDir(sharedRoot = false) Path dataFolder, Injector injector) {
        this.dataFolder = dataFolder;
        this.logger = logger;
        this.injector = injector.createChildInjector(binder -> binder.bind(ChangeSkinCore.class).toInstance(core));
    }

    @Listener
    public void onPreInit(org.spongepowered.api.event.lifecycle.ConstructPluginEvent preInitEvent) {
        //load config and database
        try {
            core.load(true);
            initialized = true;
        } catch (Exception ex) {
            logger.error("Error initializing plugin. Disabling...", ex);
        }
    }

    @Listener
    public void onInit(RegisterCommandEvent cmdEvent) {
        if (!initialized)
            return;

        //command and event register
        cmdEvent.register(injector.getInstance(SelectCommand.class).buildSpec(), this, "skin-select", "skinselect");
        cmdEvent.register(injector.getInstance(InfoCommand.class).buildSpec(), this, "skin-info");
        cmdEvent.register(injector.getInstance(UploadCommand.class).buildSpec(), this, "skin-upload");
        cmdEvent.register(injector.getInstance(SetCommand.class).buildSpec(), this, "changeskin", "setskin", "skin");
        cmdEvent.register(injector.getInstance(InvalidateCommand.class)
                .buildSpec(), this, "skininvalidate", "skin-invalidate");

        Sponge.eventManager().registerListeners(this, injector.getInstance(LoginListener.class));

        //incoming channel
        String updateChannelName = new NamespaceKey(ARTIFACT_ID, UPDATE_SKIN_CHANNEL).getCombinedName();
        String permissionChannelName = new NamespaceKey(ARTIFACT_ID, CHECK_PERM_CHANNEL).getCombinedName();

        PluginChannel updateChannel = Sponge.channelManager().getOrCreate(this, updateChannelName, RawDataPluginChannel.class);
        PluginChannel permChannel = Sponge.channelManager().getOrCreate(this, permissionChannelName, RawDataPluginChannel.class);

        ((RawDataPluginChannel) updateChannel).addListener(injector.getInstance(UpdateSkinListener.class));
        ((RawDataPluginChannel) permChannel).addListener(injector.getInstance(CheckPermissionListener.class));
    }

    @Listener
    public void onShutdown(ShutdownGameEvent stoppingServerEvent) {
        core.close();
    }

    public ChangeSkinCore getCore() {
        return core;
    }

    @Override
    public boolean hasSkinPermission(CommandSource invoker, UUID uuid, boolean sendMessage) {
        if (invoker.hasPermission(PomData.ARTIFACT_ID + ".skin.whitelist." + uuid)) {
            return true;
        }

        //disallow - not whitelisted or blacklisted
        if (sendMessage) {
            sendMessage(invoker, "no-permission");
        }

        return false;
    }

    public SpongeSkinAPI getApi() {
        return api;
    }

    @Override
    public String getName() {
        return PomData.NAME;
    }

    @Override
    public Path getPluginFolder() {
        return dataFolder;
    }

    @Override
    public Logger getLog() {
        return logger;
    }

    @Override
    public void sendMessage(CommandSource receiver, String key) {
        String message = core.getMessage(key);
        if (message != null && receiver != null) {
            Component component = LegacyComponentSerializer.legacySection().deserialize(message);
            receiver.sendMessage(component);
        }
    }
}

