    @Inject
    private ChangeSkinSponge plugin;

    @Override
    public void handle(RawPayload payload) {
        ByteArrayDataInput dataInput = ByteStreams.newDataInput(payload.data());
        SkinUpdateMessage updateMessage = new SkinUpdateMessage();
